#include <bits/stdc++.h>
using namespace std;
using ll = long long;
int main() {
	// your code goes here
	ios_base::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int t;
	cin>>t;
	while(t--){
	    int n;
	    cin>>n;
	    vector<ll> a(3*n);
	    
	    for(ll &x:a)cin>>x;
	    
	    sort(a.begin(), a.end(), greater<ll>());
	    
	    vector<ll> s(3*n+1,0);
	    
	    for(int i=0;i<3*n;i++){
	        s[i+1]=s[i]+a[i];
	    }
	    auto val = [&](int r, int q)-> ll {
	        int p = n-q-r;
	        
	        int x = p;
	        int y=p+2*q;
	        int z = y+3*r;
	        
	        return 2*s[x]+s[y]+3*s[z];
	    };
	    
	    auto dif = [&](int r, int q) -> ll{
	        int p = n-q-r;
	        int y = n+q-r;
	        int z = n+q+2*r;
	        
	        return -2LL*a[p-1]+a[y]+3LL*a[z];
	    };
	    
	    ll ans=0;
	    
	    for(int r=0;r<=n;r++){
	        int mx=n-r;
	        
	        int l=0,h=mx;
	        
	        while(l<h){
	            int m = (l+h)/2;
	            
	            if(dif(r,m)>=0)l=m+1;
	            else
	            h=m;
	        }
	        ans = max(ans, val(r,l));
	    }
	    cout<<ans<<'\n';
	    
	}
	return 0;
}
